package com.megapro.tiltmuncher.audio

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool
import com.megapro.tiltmuncher.R
import com.megapro.tiltmuncher.game.GameSounds
import com.megapro.tiltmuncher.game.LoopKind

/** SoundPool-backed implementation of [GameSounds]. Clips are generated by tools/gen_sounds.py. */
class Sounds(appContext: Context) : GameSounds {
  private val pool: SoundPool =
    SoundPool.Builder()
      .setMaxStreams(6)
      .setAudioAttributes(
        AudioAttributes.Builder()
          .setUsage(AudioAttributes.USAGE_GAME)
          .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
          .build()
      )
      .build()

  private val loaded = HashSet<Int>()
  private val ctx: Context = appContext.applicationContext
  private fun load(res: Int): Int = pool.load(ctx, res, 1)

  private val sparkA = load(R.raw.spark_a)
  private val sparkB = load(R.raw.spark_b)
  private val surgePickup = load(R.raw.surge_pickup)
  private val surgeLoop = load(R.raw.surge_loop)
  private val sirenLoop = load(R.raw.siren_loop)
  private val sentinelEaten = load(R.raw.sentinel_eaten)
  private val death = load(R.raw.death)
  private val startJingle = load(R.raw.start_jingle)
  private val levelClear = load(R.raw.level_clear)
  private val bonus = load(R.raw.bonus)
  private val extraLife = load(R.raw.extra_life)

  private var loopStream = 0
  private var loopKind = LoopKind.NONE
  private var loopRate = 1f

  init {
    pool.setOnLoadCompleteListener { _, sampleId, status -> if (status == 0) loaded.add(sampleId) }
  }

  private fun play(id: Int, volume: Float = 1f, loop: Int = 0, rate: Float = 1f): Int =
    if (id in loaded) pool.play(id, volume, volume, 1, loop, rate) else 0

  override fun spark(alternate: Boolean) {
    play(if (alternate) sparkB else sparkA, 0.8f)
  }

  override fun surgePickup() {
    play(surgePickup)
  }

  override fun sentinelEaten() {
    play(sentinelEaten)
  }

  override fun death() {
    play(death)
  }

  override fun startJingle() {
    play(startJingle)
  }

  override fun levelClear() {
    play(levelClear)
  }

  override fun bonus() {
    play(bonus)
  }

  override fun extraLife() {
    play(extraLife)
  }

  override fun loop(kind: LoopKind, rate: Float) {
    if (kind == loopKind && rate == loopRate && (kind == LoopKind.NONE || loopStream != 0)) return
    if (loopStream != 0) pool.stop(loopStream)
    loopStream = 0
    loopKind = kind
    loopRate = rate
    loopStream = when (kind) {
      LoopKind.NONE -> 0
      LoopKind.SIREN -> play(sirenLoop, 1f, -1, rate)
      LoopKind.SURGE -> play(surgeLoop, 1f, -1, 1f)
    }
  }

  /** Silence everything (app going to background). The game restarts the loop when it resumes. */
  fun pauseAll() {
    pool.autoPause()
    if (loopStream != 0) pool.stop(loopStream)
    loopStream = 0
    loopKind = LoopKind.NONE
  }

  fun release() = pool.release()
}
